trigger:
is_triggered_only = yes
trigger = {
		is_under_colonization = no
		is_colony = yes
		owner = {
			is_country_type = default
		}
		pop_amount > 500
		num_unemployed > 500 #early out before the expensive count_owned_pop to come
		NOR = {
			has_carrier_flag = criminal_underworld_disappeared # Cooldown
			has_carrier_flag = criminal_underworld_event_up
			has_carrier_flag = shattered_frontier_planet
			has_modifier = unemployment_benefits
			has_modifier = activity_program
			has_modifier = standby_mode
			has_criminal_underworld_modifier = yes
			has_drone_deviancy_modifier = yes
			has_modifier = drone_corruption
			has_gang_wars_modifier = yes
			has_center_of_drug_trade_modifier = yes
			has_mob_rule_modifier = yes
		}
		OR = {
			AND = {
				owner = { is_gestalt = no }
				count_owned_pop_amount = {
					limit = {
						is_unemployed = yes
						is_shackled_robot = no
						is_enslaved = no
						NOR = {
							has_living_standard = { type = living_standard_utopian }
							has_living_standard = { type = living_standard_good }
							has_living_standard = { type = living_standard_shared_burden }
							has_living_standard = { type = living_standard_worker_ownership }
						}
					}
					count > 500
				}
			}
			AND = {
				owner = { is_gestalt = yes }
				count_owned_pop_amount = {
					limit = {
						is_unemployed = yes
						NOT = { has_living_standard = { type = living_standard_organic_trophy } }
					}
					count > 1000
				}
			}
		}
	}

script:
carrier_event = {
	id = crime.1
	title = crime.1.name
	desc = {
		trigger = {
			if = {
				limit = { owner = { is_gestalt = no } }
				text = crime.1.desc

				if = {
					limit = { owner = { is_twisted_experimenters_empire = yes } }
					text = newline
					text = crime.1.desc.experimenters
				}
			}
			else_if = {
				limit = { owner = { is_hive_empire = yes } }
				text = crime.1.b.desc

				if = {
					limit = { owner = { is_twisted_experimenters_empire = yes } }
					text = newline
					text = crime.1.b.desc.experimenters
				}
			}
			else_if = {
				limit = { owner = { is_machine_empire = yes } }
				text = crime.1.c.desc
			}
		}
	}
	picture = {
		trigger = {
			owner = { is_gestalt = no }
		}
		picture = GFX_evt_dark_alley
	}
	picture = {
		trigger = {
			owner = { is_hive_empire = yes }
		}
		picture = GFX_evt_hive_mind
	}
	picture = {
		trigger = {
			owner = { is_machine_empire = yes }
		}
		picture = GFX_evt_glitchy_matrix
	}
	show_sound = event_criminal_activity
	location = root
	is_triggered_only = yes

	pre_triggers = {
		has_owner = yes
	}

	trigger = {
		is_under_colonization = no
		is_colony = yes
		owner = {
			is_country_type = default
		}
		pop_amount > 500
		num_unemployed > 500 #early out before the expensive count_owned_pop to come
		NOR = {
			has_carrier_flag = criminal_underworld_disappeared # Cooldown
			has_carrier_flag = criminal_underworld_event_up
			has_carrier_flag = shattered_frontier_planet
			has_modifier = unemployment_benefits
			has_modifier = activity_program
			has_modifier = standby_mode
			has_criminal_underworld_modifier = yes
			has_drone_deviancy_modifier = yes
			has_modifier = drone_corruption
			has_gang_wars_modifier = yes
			has_center_of_drug_trade_modifier = yes
			has_mob_rule_modifier = yes
		}
		OR = {
			AND = {
				owner = { is_gestalt = no }
				count_owned_pop_amount = {
					limit = {
						is_unemployed = yes
						is_shackled_robot = no
						is_enslaved = no
						NOR = {
							has_living_standard = { type = living_standard_utopian }
							has_living_standard = { type = living_standard_good }
							has_living_standard = { type = living_standard_shared_burden }
							has_living_standard = { type = living_standard_worker_ownership }
						}
					}
					count > 500
				}
			}
			AND = {
				owner = { is_gestalt = yes }
				count_owned_pop_amount = {
					limit = {
						is_unemployed = yes
						NOT = { has_living_standard = { type = living_standard_organic_trophy } }
					}
					count > 1000
				}
			}
		}
	}

	immediate = {
		set_carrier_flag = criminal_underworld_event_up
	}

	weight_multiplier = {
		factor = 1
	}

	# Top Option
	option = {
		trigger = {
			owner = { is_gestalt = no }
		}
		name = {
			trigger = {
				if = {
					limit = { owner = { is_twisted_experimenters_empire = yes } }
					text = crime.1.a.experimenters
				}
				else = {
					text = crime.1.a
				}
			}
		}
		add_modifier = { modifier = "unemployment_benefits" days = 3600 }
	}
	option = {
		trigger = {
			owner = { is_hive_empire = yes }
		}
		name = {
			trigger = {
				if = {
					limit = { owner = { is_twisted_experimenters_empire = yes } }
					text = crime.1.a2.experimenters
				}
				else = {
					text = crime.1.a2
				}
			}
		}
		add_modifier = { modifier = "activity_program" days = 3600 }
	}
	option = {
		trigger = {
			owner = { is_machine_empire = yes }
		}
		name = crime.1.a3
		custom_tooltip = crime.1.a3.tooltip
		hidden_effect = { add_modifier = { modifier = "standby_mode" days = 3600 } }
	}

	# Bottom Option
	option = {
		trigger = {
			owner = { is_twisted_experimenters_empire = yes }
		}
		name = {
			trigger = {
				if = {
					limit = { owner = { is_gestalt = no } }
					text = crime.1.b.experimenters
				}
				else_if = {
					limit = { owner = { is_hive_empire = yes } }
					text = crime.1.b2.experimenters
				}
			}
		}
		if = {
			limit = { owner = { is_gestalt = no } }
			add_modifier = { modifier = "criminal_underworld_experimenters" days = -1 }
		}
		else_if = {
			limit = { owner = { is_hive_empire = yes } }
			add_modifier = { modifier = "drone_deviancy_experimenters" days = -1 }
		}
	}
	option = {
		trigger = {
			owner = {
				is_gestalt = no
				is_twisted_experimenters_empire = no
			}
		}
		name = crime.1.b
		add_modifier = { modifier = criminal_underworld days = -1 }
	}
	option = {
		trigger = {
			owner = {
				is_hive_empire = yes
				is_twisted_experimenters_empire = no
			}
		}
		name = crime.1.b2
		add_modifier = { modifier = drone_deviancy days = -1 }
	}
	option = {
		trigger = {
			owner = { is_machine_empire = yes }
		}
		name = crime.1.b3
		add_modifier = { modifier = drone_corruption days = -1 }
	}

	after = {
		hidden_effect = { remove_carrier_flag = criminal_underworld_event_up }
	}
}

